/** Browser-decodable AVC MP4 with one video track and deliberately no audio track. */
const VIDEO_ONLY_MP4_BASE64 = '';

export function videoOnlyMp4FixtureBytes(): Uint8Array {
  const binary = atob(VIDEO_ONLY_MP4_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
